-- playerbots_dungeon_route: mod-dungeon-lead 模块的副本路线数据（按 LFG 条目记录 boss 顺序）
-- 来源：modules/mod-dungeon-lead/sql/playerbots_dungeon_route.sql（上游 Sugyn/mod-playerbots-dungeon-lead v0.12.0-alpha）
-- 414 行 / 96 个 LFG 副本 / 51 张地图；kind 分布 boss 254、optional 82、event 44、door 14、skip 14、heroic_only 6
-- By leewheel 2026-10-05
DROP TABLE IF EXISTS `playerbots_dungeon_route`;
CREATE TABLE IF NOT EXISTS `playerbots_dungeon_route` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lfg_id` INT UNSIGNED NOT NULL,
  `map_id` INT UNSIGNED NOT NULL,
  `difficulty` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `name` VARCHAR(64) NOT NULL,
  `wing` VARCHAR(32) NOT NULL DEFAULT '-',
  `step` INT UNSIGNED NOT NULL,
  `kind` VARCHAR(16) NOT NULL,
  `boss` VARCHAR(64) NOT NULL,
  `entry` INT UNSIGNED NULL,
  `x` FLOAT NULL, `y` FLOAT NULL, `z` FLOAT NULL,
  `note` VARCHAR(255) NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `lfg_step` (`lfg_id`,`step`), KEY `map` (`map_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `playerbots_dungeon_route`;
